python3 -c "
import json
with open('/app/resources/treasury_bulletin_1950_04.json') as f:
    data = json.load(f)

# Let's look for tables with 'exchange' in the data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'exchange' in k.lower() or 'pound' in k.lower() or 'sterling' in k.lower() or 'gbp' in k.lower():
                print(f'{path}.{k}: {v}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
"
